rnp_result_t rr = rnp_output_to_callback(&out, writer, closer, ctx);
if ((rr != 0) || !out) { FUZZ_BAIL(); }
// Box and annotate
rnp_output_t *output = new rnp_output_t; *output = out;
FUZZ_SET_ATTR_INT(output, "alive", 1);
FUZZ_SET_ATTR_STR(output, "kind", "callback");
// Validation: supplies valid callbacks; boxed handle preserved for later writes.

// Initialize a null sink output that discards all data
rnp_output_t out = nullptr;
rnp_result_t rr = rnp_output_to_null(&out);
if ((rr != 0) || !out) { FUZZ_BAIL(); }
// Box and annotate
rnp_output_t *output = new rnp_output_t; *output = out;
FUZZ_SET_ATTR_INT(output, "alive", 1);
FUZZ_SET_ATTR_STR(output, "kind", "null");
// Validation: returns a live null sink output for reuse.

// Write random data to an initialized output
if (FUZZ_GET_ATTR_INT(output, "alive") != 1) { FUZZ_BAIL(); }
std::string data = FUZZ_PARAM_STR();
size_t written = 0;
( void ) rnp_output_write(*output, (const void*)data.data(), data.size(), &written);
// Validation: supplies non-null data pointer and size; keeps output alive.

// Finish writing to output (especially relevant for random-temp file outputs)
if (FUZZ_GET_ATTR_INT(output, "alive") != 1) { FUZZ_BAIL(); }
( void ) rnp_output_finish(*output);
// Validation: enforces liveness; preserves handle for potential further use/destroy.

// Destroy an output stream and free resources
if (FUZZ_GET_ATTR_INT(output, "alive") != 1) { FUZZ_BAIL(); }
( void ) rnp_output_destroy(*output);
FUZZ_SET_ATTR_INT(output, "alive", 0);
// Validation: liveness enforced; do not return destroyed handle.

// Create an encryption operation context for streaming encryption
if (FUZZ_GET_ATTR_INT(ffi, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(input, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(output, "alive") != 1) { FUZZ_BAIL(); }
rnp_op_encrypt_t ctx = nullptr;
rnp_result_t rr = rnp_op_encrypt_create(&ctx, *ffi, *input, *output);
if ((rr != 0) || !ctx) { FUZZ_BAIL(); }
// Box and annotate encrypt op
rnp_op_encrypt_t *op = new rnp_op_encrypt_t; *op = ctx;
FUZZ_SET_ATTR_INT(op, "alive", 1);
FUZZ_SET_ATTR_INT(op, "has_recipient", 0);
FUZZ_SET_ATTR_INT(op, "has_signer", 0);
FUZZ_SET_ATTR_PTR(op, "ffi", (void*)*ffi);
// Validation: ensures all handles are live; returns a live encrypt op with state attributes.

// Add a recipient public key to the encryption context
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(key, "alive") != 1) { FUZZ_BAIL(); }
( void ) rnp_op_encrypt_add_recipient(*op, *key);
FUZZ_SET_ATTR_INT(op, "has_recipient", 1);
// Validation: liveness enforced; marks op as having at least one recipient.

// Add a signing key so the encryption operation will also sign
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(key, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(key, "has_secret") != 1) { FUZZ_BAIL(); }
rnp_op_sign_signature_t s = nullptr;
rnp_result_t rr = rnp_op_encrypt_add_signature(*op, *key, &s);
if ((rr != 0) || !s) { FUZZ_BAIL(); }
// Box per-signature handle (owned by op; do not destroy separately)
rnp_op_sign_signature_t *sig = new rnp_op_sign_signature_t; *sig = s;
FUZZ_SET_ATTR_INT(sig, "alive", 1);
FUZZ_SET_ATTR_PTR(sig, "owner", (void*)*op);
FUZZ_SET_ATTR_INT(op, "has_signer", 1);
// Validation: enforces op/key liveness and secret presence; boxes per-signature config handle.

// Set default hash for signatures in encrypt-and-sign mode
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
const char *hashes[] = {"MD5","SHA1","RIPEMD160","SHA256","SHA384","SHA512","SHA224","SM3"};
const char *hash = hashes[*FUZZ_PARAM(unsigned int) % 8u];
( void ) rnp_op_encrypt_set_hash(*op, hash);
// Validation: supplies supported hash string; op preserved.

// Set default signature creation time for encrypt-and-sign mode on a live op
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
uint32_t create = (uint32_t)*FUZZ_PARAM(unsigned int);
( void ) rnp_op_encrypt_set_creation_time(*op, create);
// Validation: op liveness enforced; 32-bit timestamp provided.

// Set default signature expiration time (seconds since creation, 0=no expiry) for encrypt-and-sign mode
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
uint32_t expire = (uint32_t)(*FUZZ_PARAM(unsigned int) % 315576000u); // cap ~10y for reasonableness
( void ) rnp_op_encrypt_set_expiration_time(*op, expire);
// Validation: op liveness enforced; reasonable expiration value supplied.

// Add a password-based encryption entry; marks op as having a password path
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
// Either pass explicit password or request via provider (NULL)
bool use_provider = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
std::string pw = FUZZ_PARAM_STR();
const char *password = use_provider ? (const char *)nullptr : pw.c_str();
// Optional S2K parameters (NULL means default)
const char *hashes[] = {nullptr, "SHA256", "SHA512", "SM3"};
const char *s2k_hash = hashes[*FUZZ_PARAM(unsigned int) % 4u];
size_t iterations = (size_t)(*FUZZ_PARAM(unsigned int) % 100000u); // 0 auto-calculated
const char *ciphers[] = {nullptr, "AES256", "AES128", "TWOFISH", "CAMELLIA256", "SM4"};
const char *s2k_cipher = ciphers[*FUZZ_PARAM(unsigned int) % 6u];
( void ) rnp_op_encrypt_add_password(*op, password, s2k_hash, iterations, s2k_cipher);
// Flag that password-based encryption is configured (precondition for execute)
FUZZ_SET_ATTR_INT(op, "has_password", 1);
// Validation: live op enforced; parameters meet API; attribute records password configuration.

// Enable/disable ASCII armor for encryption output
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
bool armored = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
( void ) rnp_op_encrypt_set_armor(*op, armored);
// Validation: op liveness enforced; boolean as required.

// Select supported content-encryption cipher
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
const char *ciphers[] = {"IDEA","TRIPLEDES","CAST5","BLOWFISH","AES128","AES192","AES256","TWOFISH","CAMELLIA128","CAMELLIA192","CAMELLIA256","SM4"};
const char *cipher = ciphers[*FUZZ_PARAM(unsigned int) % 12u];
( void ) rnp_op_encrypt_set_cipher(*op, cipher);
// Validation: op liveness enforced; supported cipher string provided.

// Configure AEAD algorithm ("None" or supported value)
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
const char *algs[] = {"None", "OCB"};
const char *alg = algs[*FUZZ_PARAM(unsigned int) % 2u];
( void ) rnp_op_encrypt_set_aead(*op, alg);
// Validation: op liveness enforced; algorithm constrained to allowed values.

// Set AEAD chunk size bits in 0..16 range
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
int bits = (int)(*FUZZ_PARAM(unsigned int) % 17u); // 0..16
( void ) rnp_op_encrypt_set_aead_bits(*op, bits);
// Validation: op liveness enforced; bits within documented range.

// Set compression algorithm and level (0..9)
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
const char *algs[] = {"Uncompressed", "ZIP", "ZLIB", "BZip2"};
const char *alg = algs[*FUZZ_PARAM(unsigned int) % 4u];
int level = (int)(*FUZZ_PARAM(unsigned int) % 10u); // 0..9
( void ) rnp_op_encrypt_set_compression(*op, alg, level);
// Validation: op liveness enforced; supported compression and level used.

// Set additional encryption flags (OR of RNP_ENCRYPT_*)
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
uint32_t flags = (uint32_t)*FUZZ_PARAM(unsigned int);
( void ) rnp_op_encrypt_set_flags(*op, flags);
// Validation: op liveness enforced; arbitrary supported mask provided.

// Set embedded file name (may use special "_CONSOLE")
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
std::string fname = FUZZ_PARAM_STR();
if (fname.empty()) { fname = "_CONSOLE"; }
( void ) rnp_op_encrypt_set_file_name(*op, fname.c_str());
// Validation: op liveness enforced; non-null C-string passed.

// Set file modification time (seconds since epoch)
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
uint32_t mtime = (uint32_t)*FUZZ_PARAM(unsigned int);
( void ) rnp_op_encrypt_set_file_mtime(*op, mtime);
// Validation: op liveness enforced; 32-bit timestamp provided.

// Execute encryption; must have at least one recipient and/or password configured
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
int has_recipient = FUZZ_GET_ATTR_INT(op, "has_recipient");
int has_password  = FUZZ_GET_ATTR_INT(op, "has_password");
if (!has_recipient && !has_password) { FUZZ_BAIL(); }
rnp_result_t rr = rnp_op_encrypt_execute(*op);
if (rr == 0) { FUZZ_SET_ATTR_INT(op, "executed", 1); }
// Validation: preconditions enforced via attributes; execution status recorded on success.

// Destroy the encryption operation context; must be alive
if (FUZZ_GET_ATTR_INT(op, "alive") != 1) { FUZZ_BAIL(); }
( void ) rnp_op_encrypt_destroy(*op);
FUZZ_SET_ATTR_INT(op, "alive", 0);
// Validation: correct lifetime handling; op removed from pool post-destroy.

// Decrypt data from input to output using a live FFI
if (FUZZ_GET_ATTR_INT(ffi, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(input, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(output, "alive") != 1) { FUZZ_BAIL(); }
( void ) rnp_decrypt(*ffi, *input, *output);
// Validation: all handles verified alive; keep them for reuse regardless of result.

// Get raw public key packets; free returned buffer
if (FUZZ_GET_ATTR_INT(handle, "alive") != 1) { FUZZ_BAIL(); }
uint8_t *buf = nullptr; size_t len = 0;
( void ) rnp_get_public_key_data(*handle, &buf, &len);
if (buf) { rnp_buffer_destroy(buf); }
// Validation: key liveness enforced; non-null outputs provided and freed.

// Get raw secret key data; free returned buffer
if (FUZZ_GET_ATTR_INT(handle, "alive") != 1) { FUZZ_BAIL(); }
uint8_t *buf = nullptr; size_t len = 0;
( void ) rnp_get_secret_key_data(*handle, &buf, &len);
if (buf) { rnp_buffer_destroy(buf); }
// Validation: key liveness enforced; outputs provided and freed safely.

// Serialize key information to JSON and free the result string
if (FUZZ_GET_ATTR_INT(handle, "alive") != 1) { FUZZ_BAIL(); }
uint32_t flags = 0; // keep minimal; caller may set RNP_JSON_* elsewhere
char *json = nullptr;
( void ) rnp_key_to_json(*handle, flags, &json);
if (json) { rnp_buffer_destroy(json); }
// Validation: non-null output pointer supplied and freed; key preserved.

// Create an iterator over identifiers of a supported type
if (FUZZ_GET_ATTR_INT(ffi, "alive") != 1) { FUZZ_BAIL(); }
const char *types[] = {"userid", "keyid", "grip", "fingerprint"};
const char *itype = types[*FUZZ_PARAM(unsigned int) % 4u];
rnp_identifier_iterator_t i = nullptr;
rnp_result_t rr = rnp_identifier_iterator_create(*ffi, &i, itype);
if ((rr != 0) || !i) { FUZZ_BAIL(); }
// Box and annotate iterator for pool reuse
rnp_identifier_iterator_t *it = new rnp_identifier_iterator_t; *it = i;
FUZZ_SET_ATTR_INT(it, "alive", 1);
FUZZ_SET_ATTR_PTR(it, "ffi", (void*)*ffi);
// Validation: ffi liveness enforced; supported identifier_type used; iterator boxed for subsequent APIs.

// Advance a live identifier iterator and retrieve the next identifier pointer (owned by iterator)
if (FUZZ_GET_ATTR_INT(it, "alive") != 1) { FUZZ_BAIL(); }
const char *identifier = nullptr;
( void ) rnp_identifier_iterator_next(*it, &identifier);
// Do not free 'identifier'; lifetime is tied to iterator and invalidated on next call/destroy
// Validation: enforces iterator liveness, supplies non-null storage, preserves iterator for reuse.

// Pipe data from an opened input to a valid output
if (FUZZ_GET_ATTR_INT(input, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(output, "alive") != 1) { FUZZ_BAIL(); }
( void ) rnp_output_pipe(*input, *output);
// Validation: ensures both handles are live; preserves them for further use.

// Configure line length for an armored output stream; must be an armored output
if (FUZZ_GET_ATTR_INT(output, "alive") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(output, "armored") != 1) { FUZZ_BAIL(); }
size_t llen = (size_t)((*FUZZ_PARAM(unsigned int) % 61u) + 16u); // 16..76 inclusive
( void ) rnp_output_armor_set_line_length(*output, llen);
// Validation: enforces armored-output precondition and valid range; keeps output alive.

// Retrieve backend library name string and assert non-null
const char *s = rnp_backend_string();
FUZZ_ASSERT(s != nullptr, "backend string must be non-null");
// Validation: API promises a constant string; assert non-null only.

// Retrieve backend version string and assert non-null
const char *v = rnp_backend_version();
FUZZ_ASSERT(v != nullptr, "backend version must be non-null");
// Validation: API promises a constant string; assert non-null only.

// Destroy a previously created identifier iterator; enforce liveness first
if (FUZZ_GET_ATTR_INT(it, "alive") != 1) { FUZZ_BAIL(); }
( void ) rnp_identifier_iterator_destroy(*it);
FUZZ_SET_ATTR_INT(it, "alive", 0);
// Do not return the iterator; it is now invalid.
// Validation: checks iterator liveness, calls destroy, and clears the alive attribute to prevent reuse.

