import os
import random
import string
from typing import List

# Target data type: filename path string
# Fuzzer uses FUZZ_PARAM_STR and FUZZ_PARAM_FILENAME. We will emit a bytes buffer
# containing a single path string (C-string expected by stubs). We will sometimes
# include directories that are likely to exist (., /tmp) and file names that are
# writable to help rnp_input_from_path/rnp_output_to_path/_to_file succeed.
# The harness maps FUZZ_PARAM_FILENAME to a file path with random data at that path.
# Therefore, we should provide syntactically valid paths that exercise various cases.

SAFE_DIRS_POSIX = [
    ".",
    "..",
    "/tmp",
    "/var/tmp",
    "/dev/shm",
]

SAFE_DIRS_WIN = [
    ".",
    "..",
    "C:/Windows/Temp",
    "C:/Temp",
]

# Common interesting filenames
BASENAMES = [
    "rnp_fuzz.dat",
    "keys.gpg",
    "pubring.kbx",
    "secring.gpg",
    "message.asc",
    "message.pgp",
    "cleartext.txt",
    "_CONSOLE",
    "NUL",  # Windows special
    "aux",  # reserved on Windows
]

EXTENSIONS = ["", ".gpg", ".asc", ".pgp", ".kbx", ".g10", ".bin", ".txt"]

SEPARATORS = ["/", os.sep]


def _rand_ascii(r: random.Random, n: int) -> str:
    chars = string.ascii_letters + string.digits + "-_ ."
    return "".join(r.choice(chars) for _ in range(n)).strip()


def _pick_dir(r: random.Random) -> str:
    if os.name == "nt":
        pool = SAFE_DIRS_WIN
    else:
        pool = SAFE_DIRS_POSIX
    # Occasionally use nested directories
    d = r.choice(pool)
    if r.random() < 0.4:
        extra = _rand_ascii(r, r.randint(3, 10)).replace(" ", "_")
        d = d.rstrip("/\\") + SEPARATORS[0] + extra
    return d


def _pick_basename(r: random.Random) -> str:
    if r.random() < 0.6:
        base = r.choice(BASENAMES)
    else:
        base = _rand_ascii(r, r.randint(4, 12)).strip()
        if not base:
            base = "file"
    if r.random() < 0.7:
        base += r.choice(EXTENSIONS)
    return base


def _maybe_abs(r: random.Random, path: str) -> str:
    # Sometimes ensure absolute on POSIX, drive-like on Windows
    if os.name == "nt":
        if r.random() < 0.5:
            drive = r.choice(list(string.ascii_uppercase))
            return f"{drive}:/" + path.lstrip("/\\")
        return path
    else:
        if r.random() < 0.6:
            return "/" + path.lstrip("/")
        return path


def _compose_path(r: random.Random) -> str:
    # Construct diverse but valid paths
    parts: List[str] = []
    if r.random() < 0.8:
        parts.append(_pick_dir(r))
    # add 0-2 intermediate components
    for _ in range(r.randint(0, 2)):
        parts.append(_rand_ascii(r, r.randint(3, 10)).replace(" ", "_"))
    parts.append(_pick_basename(r))
    sep = "/"
    path = sep.join(p.strip(sep + "\\") for p in parts if p)
    path = _maybe_abs(r, path)
    # Normalize some duplicates of slashes
    while "//" in path:
        path = path.replace("//", "/")
    return path


def _maybe_special(r: random.Random) -> str:
    # Occasionally return just a directory path to exercise directory-based inputs
    if r.random() < 0.2:
        return _pick_dir(r)
    # Or a simple relative file in CWD
    if r.random() < 0.2:
        return _pick_basename(r)
    return ""


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Decide which path style to generate
    special = _maybe_special(r)
    if special:
        path = special
    else:
        path = _compose_path(r)

    # Ensure length limit and non-empty
    if not path:
        path = "rnp_fuzz.dat"
    path = path[:4000]

    # Return as bytes with no trailing NUL; fuzz harness can treat as std::string/filename
    return path.encode("utf-8", errors="ignore")
